import{_ as t}from"./chunks/mujoco.Ck2gXYVb.js";import{_ as e}from"./chunks/mujoco-rbq-test.BjH2Ld70.js";import{_ as i,o as a,c as o,a5 as d}from"./chunks/framework.Cct9zD0Q.js";const g=JSON.parse('{"title":"MuJoCo","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"software/simulator/mujoco.md","filePath":"software/simulator/mujoco.md","lastUpdated":1795599730000}'),n={name:"software/simulator/mujoco.md"};function r(h,s,l,c,p,k){return a(),o("div",null,[...s[0]||(s[0]=[d('<h1 id="mujoco" tabindex="-1">MuJoCo <a class="header-anchor" href="#mujoco" aria-label="Permalink to &quot;MuJoCo&quot;">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p><strong>Open-source MuJoCo simulator for the RBQ quadruped robot.</strong></p><p>MuJoCo runs the <strong>full RBQ software stack</strong>, so <strong>SLAM research, autonomous navigation tests and every test you would run on the real robot</strong> can be done in simulation. It joins the running RBQ stack as a DDS peer, so the same RBQ software that runs on the real robot runs unchanged against the simulator.</p><table tabindex="0"><thead><tr><th style="text-align:center;">MuJoCo</th></tr></thead><tbody><tr><td style="text-align:center;"><img src="'+t+`" alt="MuJoCo" width="600"></td></tr></tbody></table><h2 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;Layout&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Path</th><th>Description</th></tr></thead><tbody><tr><td><code>src/</code></td><td>Simulator sources → <code>bin/rbq_mujoco</code></td></tr><tr><td><code>resources/model/</code></td><td>MJCF models — <code>default.xml</code> (quadruped) / <code>wheel.xml</code> (wheeled), each including the robot and <code>env/environment.xml</code></td></tr><tr><td><code>scripts/</code></td><td>Build / run (<code>mujoco.bash</code>) / Docker scripts</td></tr></tbody></table><h2 id="run" tabindex="-1">Run with the RBQ stack <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run with the RBQ stack {#run}&quot;">​</a></h2><p class="sub-title">Install</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Clone</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/RainbowRobotics/RBQ.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> RBQ</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Install dependencies (first time only)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rbq_simulator/rbq_mujoco</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/debian-dep.bash</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Build rbq_mujoco</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/build.bash</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ../../</span></span></code></pre></div><p><code>scripts/sim.bash</code> runs the RBQ stack in Docker, so Docker is the only thing to install for it — the script offers to install Docker when it is missing. The first run builds the <code>rbq-sim</code> image, which takes a few minutes. Logs go to <code>log/sim-docker/</code>, and Ctrl-C stops the stack. Settings changed from the app while it runs are not kept after it stops.</p><hr class="sub-divider"><p class="sub-title">Local</p><p><code>scripts/sim.bash --no-sim</code> starts the RBQ core SW without its own simulator and opens the web UI (<code>http://127.0.0.1:8080</code>, <code>rb</code> / <code>rainbow2026</code>) once it is up; <code>--no-gui</code> skips the browser. Then start the simulator:</p><p><strong>Quadruped</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/sim.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --vision</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-sim</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rbq_simulator/rbq_mujoco</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/rbq_mujoco</span></span></code></pre></div><p><strong>Wheeled RBQ</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/sim.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --vision</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-sim</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wheel</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rbq_simulator/rbq_mujoco</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/rbq_mujoco</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --wheel</span></span></code></pre></div><p><strong>In one command</strong> — <code>--core</code> does both steps: the simulator script also starts the RBQ core SW (<code>scripts/sim.bash --no-sim</code>) with the robot variant, LiDAR and <code>-i</code> you give the simulator. <code>--vision</code> and <code>--no-gui</code> work as above. The core SW runs in its own terminal tabs and keeps running after the simulator stops; close those tabs to stop it.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rbq_simulator/rbq_mujoco</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/mujoco.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --core</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --vision</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/mujoco.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --core</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --vision</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --wheel</span></span></code></pre></div><hr class="sub-divider"><p class="sub-title">Docker</p><p>The simulator runs in Docker and joins the RBQ stack on the host:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/sim.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --vision</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-sim</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rbq_simulator/rbq_mujoco</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/docker/run.bash</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # quadruped</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/docker/run.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --wheel</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # wheeled RBQ</span></span></code></pre></div><p><code>run.bash</code> supplies the model path itself. It handles <code>--headless</code>, <code>--build</code>, <code>--test [seconds]</code>, <code>--gpu</code> and <code>--no-check</code>, and forwards every other argument to the simulator — so <code>--wheel</code>, <code>--livox</code> and <code>--ouster</code> pass straight through. The image carries no ROS, so <code>--rviz</code> works on the host only.</p><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">NOTE — DDS networking</p><p>The simulator shares <strong>DDS domain 0</strong> on the loopback interface (<code>lo</code>) with the host RBQ stack. In Docker this is provided by <code>--network host</code>. Run only one simulator at a time: MuJoCo, Gazebo and Isaac Sim use the same topics.</p></div></div><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Meaning</th></tr></thead><tbody><tr><td><code>--wheel</code></td><td>Wheeled RBQ (12 leg joints + 4 driven wheels). Default is the quadruped</td></tr><tr><td><code>--livox</code></td><td>Livox Mid-360 x2 (front / rear). See <a href="#lidar">LiDAR</a></td></tr><tr><td><code>--ouster</code></td><td>Ouster OS1 x1 (rear deck): draws the housing only. See <a href="#lidar">LiDAR</a></td></tr><tr><td><code>-p</code>, <code>--path &lt;mjcf&gt;</code></td><td>MJCF model to load. Defaults to the selected variant&#39;s model under <code>resources/model/</code></td></tr><tr><td><code>-i</code>, <code>--interface &lt;name&gt;</code></td><td>DDS network interface. Default <code>lo</code>, which is what the on-host RBQ stack uses</td></tr><tr><td><code>--selftest [seconds]</code></td><td>Run headless for N seconds (default 3) and exit with the result. Used by <code>scripts/docker/run.bash --test</code></td></tr><tr><td><code>--rviz</code></td><td><code>mujoco.bash</code> only: also open RViz. See <a href="#ros2">ROS 2</a></td></tr><tr><td><code>--core</code></td><td><code>mujoco.bash</code> only: also start the RBQ core SW and open the web UI. With <code>--vision</code> it starts the Vision stack too; <code>--no-gui</code> skips the browser</td></tr></tbody></table><p>The wheeled RBQ needs the same variant on the RBQ stack (<code>scripts/sim.bash -r wheel</code>): wheel state and references ride <code>SimInfo_.whl_joint</code> / <code>MotionRef_.whl_joint</code>.</p><hr class="sub-divider"><p class="sub-title" id="worlds">Worlds</p><table tabindex="0"><thead><tr><th>World</th><th>File</th><th>Notes</th></tr></thead><tbody><tr><td>RBQ test world (default)</td><td><code>resources/model/env/environment.xml</code></td><td>Stairs, slopes, obstacle bars, slippery strips, docking station. Used by both <code>default.xml</code> and <code>wheel.xml</code></td></tr></tbody></table><p>To load another world, pass your own MJCF with <code>-p</code>; the joint layout still comes from the variant flag.</p><table tabindex="0"><thead><tr><th style="text-align:center;">RBQ test world (default)</th></tr></thead><tbody><tr><td style="text-align:center;"><img src="`+e+`" alt="RBQ test world" width="600"></td></tr></tbody></table><h2 id="sensors" tabindex="-1">Sensors <a class="header-anchor" href="#sensors" aria-label="Permalink to &quot;Sensors {#sensors}&quot;">​</a></h2><p class="sub-title" id="cameras">Cameras</p><p>The robot&#39;s six cameras always run and publish only to topics someone reads, so the Vision stack (HAL) reads them as it does on the robot:</p><table tabindex="0"><thead><tr><th>Sensor</th><th>Camera</th><th>Streams</th></tr></thead><tbody><tr><td><code>sensor_0</code>–<code>sensor_3</code></td><td>Bottom (front, mid-front, mid-rear, rear)</td><td>depth, IR</td></tr><tr><td><code>sensor_4</code></td><td>Front</td><td>depth, RGB</td></tr><tr><td><code>sensor_5</code></td><td>Rear</td><td>depth, RGB</td></tr></tbody></table><p>Each camera is 640 x 360 at 15 fps. Topics are <code>rt/rbq/vision/sensor_N/&lt;stream&gt;/compressed</code>, with <code>camera_info</code> and <code>tf</code> beside them.</p><hr class="sub-divider"><p class="sub-title" id="lidar">LiDAR</p><p>LiDAR is <strong>opt-in</strong> — nothing is drawn and no LiDAR runs without a flag.</p><table tabindex="0"><thead><tr><th>Flag</th><th>LiDAR</th><th>Scan</th></tr></thead><tbody><tr><td><em>(none)</em></td><td>none</td><td>—</td></tr><tr><td><code>--livox</code></td><td>Livox Mid-360 x2, <code>lidar_front</code> (+35° up) / <code>lidar_rear</code> (−35° up)</td><td>Non-repetitive Mid-360 pattern, 24000 points per frame, 50 m</td></tr><tr><td><code>--ouster</code></td><td>Ouster OS1 x1 on the rear deck, <code>lidar_ouster</code></td><td>Not simulated yet: draws the housing and adds its mass</td></tr></tbody></table><p>Each Livox scans at 10 Hz and publishes <code>rt/rbq/lidar/&lt;name&gt;</code> (PointCloud2 in the sensor frame), <code>&lt;name&gt;/imu</code> (200 Hz) and <code>&lt;name&gt;/tf</code>. The flag also adds the sensor&#39;s collision hull and mass, so the robot cannot walk under an overhang that would hit the LiDAR.</p><p>To feed it to SLAM, give the RBQ stack the same LiDAR: <code>bash scripts/sim.bash --slam --no-sim -p livox</code>. The Vision stack (HAL) turns the cloud into the frames SLAM reads.</p><hr class="sub-divider"><p class="sub-title" id="imu">IMU</p><p>The body IMU goes to Motion with the robot state every control cycle, and the RBQ stack publishes it as <code>rt/rbq/imu</code>. With <code>--livox</code> each LiDAR also has its own IMU (<code>rt/rbq/lidar/&lt;name&gt;/imu</code>, 200 Hz).</p><h2 id="ros2" tabindex="-1">ROS 2 <a class="header-anchor" href="#ros2" aria-label="Permalink to &quot;ROS 2 {#ros2}&quot;">​</a></h2><p>The simulator and the RBQ stack publish on <strong>ROS 2 domain 0</strong> over loopback (<code>lo</code>), so ROS 2 nodes see them as ordinary topics — no bridge is needed. Run your node with these environment variables (CycloneDDS is required):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> RMW_IMPLEMENTATION</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">rmw_cyclonedds_cpp</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ROS_DOMAIN_ID</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> CYCLONEDDS_URI</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">file://$(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">pwd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)/rbq_simulator/rbq_gazebo/ros2/src/sensor_bridge/config/cyclonedds_gazebo.xml   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># from the repository root</span></span></code></pre></div><p><code>lo</code> needs multicast for discovery; <code>mujoco.bash</code> turns it on (<code>sudo ip link set lo multicast on</code>).</p><p>Every topic is Reliable · KeepLast 8.</p><div class="ros-topics"><table tabindex="0"><thead><tr><th>ROS 2 Topic</th><th>Type</th><th>Note</th></tr></thead><tbody><tr><td><code>/rbq/imu</code></td><td><code>sensor_msgs/msg/Imu</code></td><td>Body IMU</td></tr><tr><td><code>/rbq/joint_states</code></td><td><code>sensor_msgs/msg/JointState</code></td><td>Joint states</td></tr><tr><td><code>/rbq/odometry</code></td><td><code>nav_msgs/msg/Odometry</code></td><td>Odometry</td></tr><tr><td><code>/tf</code></td><td><code>tf2_msgs/msg/TFMessage</code></td><td>Transforms</td></tr><tr><td><code>/rbq/lidar/lidar_front</code></td><td><code>sensor_msgs/msg/PointCloud2</code></td><td>LiDAR cloud</td></tr><tr><td><code>/rbq/lidar/lidar_rear</code></td><td><code>sensor_msgs/msg/PointCloud2</code></td><td>LiDAR cloud</td></tr><tr><td><code>/rbq/lidar/&lt;name&gt;/imu</code></td><td><code>sensor_msgs/msg/Imu</code></td><td>LiDAR IMU</td></tr><tr><td><code>/rbq/vision/sensor_N/&lt;stream&gt;/compressed</code></td><td><code>sensor_msgs/msg/CompressedImage</code></td><td>Camera image</td></tr></tbody></table></div><p><code>/tf</code> has no ground-truth chain: <code>local_world → base_link</code> is the <strong>state estimator</strong> output (IMU + leg odometry, origin at boot/reset), published by RBQ SW. MuJoCo runs in real time, so every topic is stamped with the PC&#39;s system time — do not set <code>use_sim_time</code>. The 500 Hz topics are written only while a reader is subscribed.</p><p><code>--rviz</code> opens the same RViz view as <a href="/RBQ/nightly/software/simulator/gazebo.html#ros2">Gazebo</a>. Build its package once — it needs ROS 2 Humble but not Gazebo:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/ros/humble/setup.bash</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rbq_simulator/rbq_gazebo/ros2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">colcon</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --symlink-install</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rbq_simulator/rbq_mujoco</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/mujoco.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --rviz</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/mujoco.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --livox</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --rviz</span></span></code></pre></div><table tabindex="0"><thead><tr><th></th><th>MuJoCo</th><th>Gazebo</th></tr></thead><tbody><tr><td>Time base</td><td>PC system time</td><td>simulation time (<code>/clock</code>, <code>use_sim_time</code>)</td></tr><tr><td>Joint states</td><td><code>/rbq/joint_states</code> (RBQ stack)</td><td><code>/joint_states</code> (Gazebo bridge)</td></tr><tr><td>Livox cloud</td><td><code>/rbq/lidar/lidar_*</code></td><td><code>/rbq/lidar/lidar_*/points</code></td></tr></tbody></table><p>Joint states and the Fixed Frame <code>local_world</code> come from the RBQ stack, so run it alongside.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/RBQ/nightly/software/simulator/gazebo.html">Gazebo</a> — Ignition Gazebo simulator</li><li><a href="/RBQ/nightly/software/simulator/isaac-sim.html">Isaac Sim</a> — Isaac Sim simulator</li><li><a href="/RBQ/nightly/software/simulator/rbq-gym.html">Isaac Gym</a> / <a href="/RBQ/nightly/software/simulator/rbq-lab.html">Isaac Lab</a> — RL training environments</li><li><a href="/RBQ/nightly/software/simulator/overview.html">Simulator overview</a></li></ul>`,61)])])}const y=i(n,[["render",r]]);export{g as __pageData,y as default};
